<?php
 namespace Pterodactyl\Services\Dezerx\Ai; use Illuminate\Support\Facades\Log; class OpenAiProvider implements ChatProvider { private const OPENAI = 'https://api.openai.com/v1'; private const ECHO = [ 'openai' => [], 'gemini' => [], 'xai' => [], 'groq' => [], 'mistral' => [], 'openrouter' => ['reasoning', 'reasoning_details', 'reasoning_content'], ]; private const ECHO_DEFAULT = ['reasoning_content']; private const TOOL_BUDGET = 160000; private const KEEP_RECENT = 4; private const CONTINUATIONS = 2; public function __construct( private readonly string $key, private string $model, private readonly int $maxSteps, private readonly string $baseUrl = '', private readonly string $provider = 'custom', private readonly string $session = '', ) { } public function converse(string $system, array $history, ToolBox $tools): AiReply { $definitions = array_map(fn (array $tool) => [ 'type' => 'function', 'function' => ['name' => $tool['name'], 'description' => $tool['description'], 'parameters' => $tool['schema']], ], $tools->definitions()); $messages = [['role' => 'system', 'content' => $system]]; foreach ($history as $turn) { $messages[] = ['role' => $turn['role'], 'content' => $turn['content']]; } $text = ''; $partial = ''; $finished = false; $continued = 0; for ($step = 0; $step < $this->maxSteps; ++$step) { if ($step > 0 && $tools->outOfTime()) { break; } $choice = $tools->pending() !== [] ? 'none' : 'auto'; try { [$message, $finish] = $this->send($messages, $definitions, $tools, $choice); } catch (AiUnavailable $exception) { if ($choice !== 'none') { throw $exception; } $finished = true; break; } $raw = self::text($message['content'] ?? null, false); $said = trim($raw); $calls = $choice === 'none' ? [] : $this->calls($message, $step); if ($calls === []) { if ($finish === 'length' && $said !== '' && $continued < self::CONTINUATIONS) { $partial .= $raw; $messages[] = ['role' => 'assistant', 'content' => $raw]; $messages[] = ['role' => 'user', 'content' => 'Continue exactly where you stopped, without repeating anything.']; $continued++; continue; } $text = trim($partial . $raw) ?: $text; $finished = true; break; } if ($said !== '') { $text = $said; } $messages[] = $this->assistantTurn($message, $calls); foreach ($calls as $call) { $arguments = self::arguments($call['function']['arguments'] ?? ''); $messages[] = [ 'role' => 'tool', 'tool_call_id' => $call['id'], 'content' => $arguments === null ? $tools->invalid((string) ($call['function']['name'] ?? '')) : $tools->run((string) ($call['function']['name'] ?? ''), $arguments), ]; } $this->compact($messages); } if (!$finished) { $text = $this->wrapUp($messages, $definitions, $tools) ?? $text; } return new AiReply($text, $tools->steps(), !$finished); } private function wrapUp(array $messages, array $definitions, ToolBox $tools): ?string { $messages[] = ['role' => 'user', 'content' => ToolBox::WRAP_UP]; try { $tools->extendForWrapUp(); [$message] = $this->send($messages, $definitions, $tools, 'none'); } catch (Stopped $stopped) { throw $stopped; } catch (AiUnavailable) { return null; } $said = self::text($message['content'] ?? null); return $said === '' ? null : $said; } private function headers(string $base): array { if ($this->session === '' || !str_contains($base, 'opencode.ai/zen/go')) { return []; } return ['x-opencode-session' => $this->session, 'User-Agent' => 'DezerX-Stark-Assistant/1.0']; } private function send(array $messages, array $tools, ToolBox $toolbox, string $choice = 'auto'): array { $base = $this->baseUrl !== '' ? rtrim($this->baseUrl, '/') : self::OPENAI; $trimmed = false; $swapped = false; while (true) { $body = ['model' => $this->model, 'messages' => $messages]; if ($tools !== []) { $body['tools'] = $tools; $body['tool_choice'] = $choice; } $response = ModelHttp::post($base . '/chat/completions', $this->headers($base), $body, $toolbox, $this->key === 'local' ? null : $this->key); if ($response->successful()) { break; } $replacement = ModelHttp::replacement($response); if (!$swapped && $replacement !== null && $replacement !== $this->model) { Log::warning('ai: model retired, using the replacement the service named', ['provider' => $this->provider, 'from' => $this->model, 'to' => $replacement]); $toolbox->note('model', "{$this->model} has been retired by the service, so {$replacement} answered instead. Update the model in the assistant settings."); $this->model = $replacement; $swapped = true; continue; } if (!$trimmed && ModelHttp::contextTooLong($response)) { $this->compact($messages, 20000, 1); $trimmed = true; continue; } ModelHttp::fail($response, $this->model); } $message = $response->json('choices.0.message'); if (!is_array($message)) { $reason = $response->json('error.message'); throw new AiUnavailable(is_string($reason) ? 'The model service failed mid-answer: ' . $reason : 'The model answered with something this panel could not read.'); } return [$message, (string) ($response->json('choices.0.finish_reason') ?? '')]; } private function calls(array $message, int $step): array { $calls = []; foreach ((array) ($message['tool_calls'] ?? []) as $index => $call) { if (!is_array($call) || !is_string($call['function']['name'] ?? null) || $call['function']['name'] === '') { continue; } unset($call['index']); $call['id'] = is_string($call['id'] ?? null) && $call['id'] !== '' ? $call['id'] : "call_{$step}_{$index}"; $call['type'] = 'function'; $arguments = $call['function']['arguments'] ?? ''; $call['function']['arguments'] = is_string($arguments) ? $arguments : json_encode($arguments ?: new \stdClass()); $calls[] = $call; } return $calls; } private function assistantTurn(array $message, array $calls): array { $turn = ['role' => 'assistant', 'content' => $message['content'] ?? null, 'tool_calls' => $calls]; foreach (self::ECHO[$this->provider] ?? self::ECHO_DEFAULT as $field) { if (isset($message[$field]) && $message[$field] !== '' && $message[$field] !== []) { $turn[$field] = $message[$field]; } } return $turn; } private static function arguments(string $raw): ?array { $raw = trim($raw); if ($raw === '' || $raw === 'null') { return []; } $decoded = json_decode($raw, true); if (!is_array($decoded)) { $decoded = json_decode(preg_replace('/^```(?:json)?\s*|\s*```$/', '', $raw) ?? '', true); } return is_array($decoded) ? $decoded : null; } private static function text(mixed $content, bool $trim = true): string { if (is_string($content)) { return $trim ? trim($content) : $content; } if (!is_array($content)) { return ''; } $parts = []; foreach ($content as $part) { if (is_array($part) && ($part['type'] ?? 'text') === 'text' && is_string($part['text'] ?? null)) { $parts[] = $part['text']; } } $text = implode("\n", $parts); return $trim ? trim($text) : $text; } private function compact(array &$messages, int $budget = self::TOOL_BUDGET, int $keep = self::KEEP_RECENT): void { $tools = array_keys(array_filter($messages, fn (array $message) => ($message['role'] ?? '') === 'tool')); $total = array_sum(array_map(fn (int $index) => strlen((string) $messages[$index]['content']), $tools)); foreach (array_slice($tools, 0, max(0, count($tools) - $keep)) as $index) { if ($total <= $budget) { return; } $content = (string) $messages[$index]['content']; if (strlen($content) <= 800) { continue; } $short = mb_strcut($content, 0, 600) . "\n[…trimmed to save room. Run the tool again if you need this.]"; $total -= strlen($content) - strlen($short); $messages[$index]['content'] = $short; } } } 